// User-gesture-only Web Audio. Vocal jump uses two short, formant-filtered hoots.
export class GameAudio {
 constructor(enabled=false){this.enabled=enabled;this.context=null;this.failed=false}
 play(kind){if(!this.enabled||this.failed)return;try{this.context??=new(window.AudioContext||window.webkitAudioContext)();const c=this.context;if(c.state==='suspended')c.resume().catch(()=>{});if(kind==='jump'){this.hoot(c.currentTime,300,540,.13);this.hoot(c.currentTime+.13,480,260,.17);return}const notes={land:110,pass:670,banana:1150,golden:1480,power:890,'shield-used':180,slide:145,stage:760,'chimpion-mode':980,'PERFECT JUMP':920,'PERFECT SLIDE':840,'CLOSE CALL':520,dead:85,record:1040,click:320};let o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.type=['banana','golden','record'].includes(kind)?'sine':'triangle';o.frequency.setValueAtTime(notes[kind]||300,c.currentTime);o.frequency.exponentialRampToValueAtTime((notes[kind]||300)*(['banana','golden','stage'].includes(kind)?1.45:.55),c.currentTime+.12);g.gain.setValueAtTime(.035,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.14);o.start();o.stop(c.currentTime+.15)}catch{this.failed=true;this.enabled=false}}
 hoot(t,start,end,length){const c=this.context,o=c.createOscillator(),filter=c.createBiquadFilter(),g=c.createGain();o.type='sawtooth';o.frequency.setValueAtTime(start,t);o.frequency.exponentialRampToValueAtTime(end,t+length*.55);o.frequency.exponentialRampToValueAtTime(start*.8,t+length);filter.type='bandpass';filter.frequency.setValueAtTime(850,t);filter.frequency.exponentialRampToValueAtTime(580,t+length);filter.Q.value=2.5;o.connect(filter);filter.connect(g);g.connect(c.destination);g.gain.setValueAtTime(.001,t);g.gain.linearRampToValueAtTime(.16,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+length);o.start(t);o.stop(t+length+.01)}
}
